"""Author the current 1.2.7 documentation from verified acceptance evidence."""
from pathlib import Path
import json
import sys
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'Документация/Актуальная_поставка_1.2.7'
E=ROOT/'Документация/04_Тестирование/Протоколы/Итоговая_приемка_1.2.7'
SH=E/'Ручные'
M=json.loads((E/'manifest.json').read_text(encoding='utf-8'))
assert M['manual_steps']==12 and M['standalone_total']==94
OUT.mkdir(exist_ok=True)

def base(title,subject):
    d=Document(); s=d.sections[0]
    s.page_width=Inches(8.5);s.page_height=Inches(11)
    s.top_margin=s.bottom_margin=Inches(.65);s.left_margin=s.right_margin=Inches(.75)
    for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
        st=d.styles[name];st.font.name='Arial';st.font.color.rgb=RGBColor(0,0,0)
        st.paragraph_format.space_after=Pt(7)
        rp=st.element.get_or_add_rPr();rf=rp.find(qn('w:rFonts'))
        if rf is not None:
            for attr in list(rf.attrib):
                if 'theme' in attr.lower():del rf.attrib[attr]
            for script in ['ascii','hAnsi','eastAsia','cs']:rf.set(qn('w:'+script),'Arial')
        lang=OxmlElement('w:lang');lang.set(qn('w:val'),'ru-RU');rp.append(lang)
    for name in ['Title','Title Char']:
        if name in d.styles:
            for border in list(d.styles[name].element.iter(qn('w:pBdr'))):border.getparent().remove(border)
    d.styles['Normal'].font.size=Pt(11)
    d.styles['Normal'].paragraph_format.line_spacing=1.1
    d.styles['Title'].font.size=Pt(25)
    d.styles['Heading 1'].font.size=Pt(17)
    d.styles['Heading 2'].font.size=Pt(13)
    d.core_properties.author='Проект Молочная ферма Луговая'
    d.core_properties.title=title;d.core_properties.subject=subject
    h=s.header.paragraphs[0];h.text='Молочная ферма Луговая   •   Версия 1.2.7'
    h.runs[0].font.size=Pt(9);h.runs[0].font.color.rgb=RGBColor(0,0,0)
    f=s.footer.paragraphs[0];f.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    f.add_run('Версия 1.2.7   /   ')
    fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');f._p.append(fld)
    d.add_paragraph(title,'Title')
    d.add_paragraph('Актуальная редакция от 21 ноября 2026 года. Учебная платформа 1С 8.3.27.1688.')
    return d
def p(d,text):d.add_paragraph(text)
def h(d,text):d.add_heading(text,level=1)
def save(d,name):
    if len(sys.argv)==1 or sys.argv[1]=='report' and name.startswith('Отчет'):
        d.save(OUT/name)
def shot(d,name,caption,width=6.7):
    d.add_picture(str(SH/name),width=Inches(width))
    c=d.add_paragraph(caption);c.runs[0].font.size=Pt(9)
def table(d,headers,rows,widths):
    t=d.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    for c,w in zip(t.columns,widths):c.width=Inches(w)
    for c,text in zip(t.rows[0].cells,headers):c.text=text
    rep=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(rep)
    for row in rows:
        for c,text in zip(t.add_row().cells,row):c.text=str(text)
    borders=OxmlElement('w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:
        el=OxmlElement('w:'+side);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'D9D9D9');borders.append(el)
    t._tbl.tblPr.append(borders)
    for i,row in enumerate(t.rows):
        for j,c in enumerate(row.cells):
            c.width=Inches(widths[j])
            c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            pr=c._tc.get_or_add_tcPr();marg=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                el=OxmlElement('w:'+side);el.set(qn('w:w'),'85');el.set(qn('w:type'),'dxa');marg.append(el)
            pr.append(marg)
            if i==0:
                sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'E6E6E6');pr.append(sh)
            for pa in c.paragraphs:
                pa.paragraph_format.space_after=Pt(3);pa.paragraph_format.line_spacing=1.03
                pa.alignment=WD_ALIGN_PARAGRAPH.CENTER if headers[j] in ['Шаг','Успешно','Итог'] else WD_ALIGN_PARAGRAPH.LEFT
                for r in pa.runs:r.font.size=Pt(9.5);r.bold=i==0
    d.add_paragraph('').paragraph_format.space_after=Pt(0)
    return t

